CREATE COLUMN TABLE "TEST_AP"."SFI10" ("DocEntry" INTEGER CS_INT NOT NULL , "LineSeq" INTEGER CS_INT NOT NULL , "AftLineNum" INTEGER CS_INT NOT NULL , "OrderNum" INTEGER CS_INT NOT NULL , "LineType" NVARCHAR(1), "LineText" NCLOB MEMORY THRESHOLD 1000, "LogInstanc" INTEGER CS_INT DEFAULT 0, "ObjType" NVARCHAR(20) DEFAULT '254000065', PRIMARY KEY ("DocEntry", "LineSeq")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "SFI10_SECONDERY" ON "TEST_AP"."SFI10" ( "DocEntry" ASC, "AftLineNum" ASC, "OrderNum" ASC )